/** 
 * Returns a new  {@link BigtableIO.Write} that will write to the Cloud Bigtable instanceindicated by the given options, and using any other specified customizations. <p>Clones the given  {@link BigtableOptions} builder so that any further changeswill have no effect on the returned  {@link BigtableIO.Write}. <p>Does not modify this object.
 */
public Write withBigtableOptions(BigtableOptions.Builder optionsBuilder){
  checkNotNull(optionsBuilder,"optionsBuilder");
  BigtableOptions options=optionsBuilder.build();
  BigtableOptions.Builder clonedBuilder=options.toBuilder().setBulkOptions(options.getBulkOptions().toBuilder().setUseBulkApi(true).build());
  BigtableOptions optionsWithAgent;
  try {
    optionsWithAgent=clonedBuilder.setUserAgent(getUserAgent()).build();
  } catch (SecurityException e) {
    // Handle the exception, e.g., log it or use a default user agent
    optionsWithAgent=clonedBuilder.setUserAgent("defaultAgent").build();
  }
  return new Write(optionsWithAgent,tableId,bigtableService);
}
